const block = (h: number, w: string = '100%') => ({
  height: h,
  width: w,
  borderRadius: 6,
  background: 'linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 50%, #e5e7eb 75%)',
  backgroundSize: '200% 100%',
  animation: 'dashboard-skeleton-shimmer 1.2s ease-in-out infinite',
} as const)

export function DashboardSkeleton() {
  return (
    <div aria-busy="true" aria-label="Loading dashboard content">
      <style>{`
        @keyframes dashboard-skeleton-shimmer {
          0% { background-position: 100% 0; }
          100% { background-position: -100% 0; }
        }
      `}</style>
      <div className="grid grid-cols-2 gap-4">
        {[0, 1].map((i) => (
          <div key={i} className="card">
            <div style={{ ...block(14), width: '55%', marginBottom: 12 }} />
            <div style={{ ...block(28), width: '72%' }} />
          </div>
        ))}
      </div>
      <div className="chart" style={{ marginTop: 24 }}>
        <div style={{ ...block(14), width: '30%', marginBottom: 16 }} />
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {[0, 1, 2, 3].map((i) => (
            <li key={i} style={{ marginBottom: 10 }}>
              <div style={block(16)} />
            </li>
          ))}
        </ul>
      </div>
      <div className="invoices" style={{ marginTop: 24 }}>
        <div style={{ ...block(14), width: '40%', marginBottom: 16 }} />
        <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
          {[0, 1, 2].map((i) => (
            <li key={i} style={{ marginBottom: 10 }}>
              <div style={block(16)} />
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}

